parameters.jsCode:
// Province goes in the query text on purpose: it is what makes retrieval pick
// Quebec's final-pay clause over Ontario's rather than the model guessing.
const event = $input.first().json.body ?? {};
const meta = Object.entries(event.metadata ?? {})
  .map(([k, v]) => `${k} ${v}`)
  .join(' ');

return [{
  json: {
    query: `${event.eventType ?? ''} ${meta} province ${event.province ?? ''} — required actions, notices, deadlines`.trim(),
  },
}];

// The vector store emits one item per retrieved chunk. Collapsing them into a
// single item here is what keeps the LLM chain to ONE call instead of three.
const event = $('Webhook').first().json.body ?? {};

// An empty store is indistinguishable from "no relevant policy" downstream, and the
// in-memory store is wiped by every container restart — so detect it explicitly rather
// than letting the run end silently with no response.
const docs = $input.all()
  .map((item) => item.json.document ?? item.json)
  .filter((d) => d && typeof d.pageContent === 'string' && d.pageContent.length > 0);

if (docs.length === 0) {
  return [{ json: { storeEmpty: true } }];
}

const excerpts = docs.map((doc, i) => {
  const source = doc.metadata?.sourceDocument ?? 'unknown';
  return `[Excerpt ${i + 1}] sourceDocument: ${source}\n${doc.pageContent}`;
}).join('\n\n');

const prompt = [
  'You are an HR compliance assistant.',
  '',
  'EVENT',
  `  eventType:     ${event.eventType ?? ''}`,
  `  employeeId:    ${event.employeeId ?? ''}`,
  `  effectiveDate: ${event.effectiveDate ?? ''}`,
  `  province:      ${event.province ?? ''}`,
  `  metadata:      ${JSON.stringify(event.metadata ?? {})}`,
  '',
  'RETRIEVED POLICY EXCERPTS',
  excerpts || '(none retrieved)',
  '',
  'RULES',
  '- Use ONLY the excerpts above. Do not apply outside knowledge of employment law.',
  '- Every action must quote the clause it rests on verbatim in sourceClause, and name the',
  '  sourceDocument it came from exactly as given above.',
  '- If the excerpts do not clearly cover this event, return an empty actions array.',
  '  Returning nothing is correct; inventing an action is not.',
  '- deadlineRuleDays is the day offset stated in the clause. Set deadline to exactly',
  `  ${event.effectiveDate ?? 'the effective date'} plus that many days.`,
  '- When a clause is province-specific, use the one matching the event province.',
  `- Set eventId to "${event.employeeId ?? ''}-${event.effectiveDate ?? ''}".`,
  `- Set eventType to "${event.eventType ?? ''}" and effectiveDate to "${event.effectiveDate ?? ''}".`,
  '- confidence (0-1) should reflect how directly the cited clause covers this event.',
].join('\n');

return [{ json: { storeEmpty: false, prompt } }];

parameters.inputSchema:
{
  "type": "object",
  "required": ["eventId", "eventType", "effectiveDate", "actions"],
  "properties": {
    "eventId": { "type": "string", "description": "employeeId-effectiveDate" },
    "eventType": { "type": "string" },
    "effectiveDate": { "type": "string", "description": "ISO date YYYY-MM-DD" },
    "actions": {
      "type": "array",
      "description": "Empty array when the excerpts do not cover the event",
      "items": {
        "type": "object",
        "required": ["actionType", "deadline", "deadlineRuleDays", "sourceClause", "sourceDocument", "confidence"],
        "properties": {
          "actionType": {
            "type": "string",
            "enum": ["send_continuation_notice", "end_benefits", "issue_final_paycheck", "request_asset_return", "notify_manager", "flag_leave_request", "schedule_return_to_work_check", "open_benefits_enrollment", "schedule_benefits_review"]
          },
          "deadline": { "type": "string", "description": "ISO date, equal to effectiveDate plus deadlineRuleDays" },
          "deadlineRuleDays": { "type": "integer", "description": "Day offset stated in the cited clause" },
          "sourceClause": { "type": "string", "description": "Verbatim text of the clause" },
          "sourceDocument": {
            "type": "string",
            "enum": ["termination.md", "leave-policy.md", "benefits-eligibility.md"]
          },
          "confidence": { "type": "number" }
        }
      }
    }
  }
}
